def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()
    write_times = {}
    results = []

    for op in ops:
        t = op[1]

        # Clean up expired entries
        expired_keys = [key for key, write_time in write_times.items() 
                       if write_time + ttl <= t]
        for key in expired_keys:
            if key in cache:
                del cache[key]
            del write_times[key]

        if op[0] == 'put':
            key, value = op[2], op[3]

            # If key already exists, remove it first
            if key in cache:
                del cache[key]
            # If cache is at capacity and key is not present, evict LRU
            elif len(cache) >= capacity:
                lru_key = next(iter(cache))
                del cache[lru_key]
                del write_times[lru_key]

            # Add the new entry as most recently used
            cache[key] = value
            write_times[key] = t

        elif op[0] == 'get':
            key = op[2]

            if key in cache and write_times[key] + ttl > t:
                # Move to end (most recently used)
                cache.move_to_end(key)
                results.append(cache[key])
            else:
                results.append(-1)

    return results

